// 日本地図（GRID.gc×GRID.gr）各升の標高。国土地理院 標高タイル（dem_png, z6）を
// prototype/tools/build_japan_elevation.mjs が一度だけ取って下ごしらえした（手で直さない）。
// 値は Int16（m）。海（cell<0）や取れなかった所は -32768（無効値）。出典：国土地理院。docs/CREDITS.md 参照。
// 陸 15081 升、標高 -4m〜2580m。
export const ELEV_SENTINEL = -32768;
export const ELEV_B64 = '';
export function decodeElevation() {
  const bin = atob(ELEV_B64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return new Int16Array(buf.buffer);
}
